import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int n = sc.nextInt();
        int k = sc.nextInt();
        double[] p = new double[n];
        for (int i = 0; i < n; i++) {
            p[i] = sc.nextDouble();
        }

        double[] ans = new double[n];
        double[] dp_state = new double[1 << n];
        int[] popcount = new int[1 << n];

        for (int mask = 1; mask < (1 << n); mask++) {
            popcount[mask] = Integer.bitCount(mask);
        }

        dp_state[0] = 1.0;

        for (int mask = 0; mask < (1 << n); mask++) {
            double total_prob = 0.0;
            for (int i = 0; i < n; i++) {
                if ((mask & (1 << i)) == 0) {
                    total_prob += p[i];
                }
            }
            if (total_prob < 1e-12) continue;
            for (int i = 0; i < n; i++) {
                if ((mask & (1 << i)) == 0) {
                    double p_i = p[i] / total_prob;
                    if (popcount[mask] < k) {
                        ans[i] += dp_state[mask] * p_i;
                    }
                    dp_state[mask | (1 << i)] += dp_state[mask] * p_i;
                }
            }
        }

        for (int i = 0; i < n; i++) {
            System.out.printf("%.12f ", ans[i]);
        }
        System.out.println();
        sc.close();
    }
}
